#include "tigersheets/recovery.hpp"
#include <QTemporaryDir>
#include <QCoreApplication>
#include <QThread>
#include <sys/wait.h>
#include <unistd.h>
#include <sqlite3.h>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>
namespace tigersheets {class RecoveryDriver;}
using namespace tigersheets;
namespace {
using Database=std::unique_ptr<sqlite3,decltype(&sqlite3_close)>;
using Statement=std::unique_ptr<sqlite3_stmt,decltype(&sqlite3_finalize)>;
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
Database database(const std::string& path){sqlite3* raw=nullptr;require(sqlite3_open(path.c_str(),&raw)==SQLITE_OK,"open test database");return {raw,sqlite3_close};}
void sql(sqlite3* db,const char* statement){require(sqlite3_exec(db,statement,nullptr,nullptr,nullptr)==SQLITE_OK,sqlite3_errmsg(db));}
Statement prepare(sqlite3* db,const char* sqlText){sqlite3_stmt* raw=nullptr;require(sqlite3_prepare_v2(db,sqlText,-1,&raw,nullptr)==SQLITE_OK,sqlite3_errmsg(db));return {raw,sqlite3_finalize};}
int version(sqlite3* db){auto statement=prepare(db,"PRAGMA user_version");require(sqlite3_step(statement.get())==SQLITE_ROW,"read database version");return sqlite3_column_int(statement.get(),0);}
Json book(){return {{"revision",9},{"sheets",Json::array()}};}
void insertLegacy(sqlite3* db,const std::string& id,const std::string& snapshot,const std::string& source,const std::string& path){auto statement=prepare(db,"INSERT INTO checkpoints(id,snapshot,source,path) VALUES(?1,?2,?3,?4)");require(sqlite3_bind_text(statement.get(),1,id.c_str(),-1,SQLITE_TRANSIENT)==SQLITE_OK,"bind legacy id");require(sqlite3_bind_blob64(statement.get(),2,snapshot.data(),snapshot.size(),SQLITE_TRANSIENT)==SQLITE_OK,"bind legacy snapshot");require(sqlite3_bind_blob64(statement.get(),3,source.data(),source.size(),SQLITE_TRANSIENT)==SQLITE_OK,"bind legacy source");require(sqlite3_bind_text64(statement.get(),4,path.data(),path.size(),SQLITE_TRANSIENT,SQLITE_UTF8)==SQLITE_OK,"bind legacy path");require(sqlite3_step(statement.get())==SQLITE_DONE,"insert legacy checkpoint");}
void roundTrip(){QTemporaryDir directory;const auto path=directory.filePath("recovery.db").toStdString();const std::string source("PK\3\4\0\xff\x80",7);{RecoveryStore store(path);store.checkpoint("model",book(),source,"/gone/model.xlsm");}{RecoveryStore store(path);const auto rows=store.records();require(rows.size()==1&&rows[0].at("workbook")==book()&&rows[0].at("sourceBytes").get<std::string>()==source&&rows[0].at("sourcePath")=="/gone/model.xlsm","unsaved workbook and exact original binary package survive process restart");store.erase("model");require(store.records().empty(),"erase checkpoint");}}
void corruption(){for(const auto* change:{"UPDATE checkpoints SET source='changed'","UPDATE checkpoints SET snapshot='{\"revision\":10}'","UPDATE checkpoints SET path='/another/model.xlsm'"}){QTemporaryDir directory;const auto path=directory.filePath("recovery.db").toStdString();RecoveryStore store(path);store.checkpoint("corrupt",book(),"original-zip","/gone/model.xlsm");{auto db=database(path);sql(db.get(),change);}bool rejected=false;try{store.records();}catch(const std::runtime_error& error){rejected=std::string(error.what()).find("corrupt")!=std::string::npos;}require(rejected,"corrupt recovery snapshot/source/path must be diagnosed");}}
void migration(){
 QTemporaryDir directory;const auto path=directory.filePath("legacy.db").toStdString();const auto snapshot=book().dump(2);const std::string source("PK\3\4\0\xff\x80",7);
 {auto db=database(path);sql(db.get(),"CREATE TABLE checkpoints(id TEXT PRIMARY KEY,snapshot BLOB NOT NULL,source BLOB NOT NULL,path TEXT NOT NULL);PRAGMA user_version=1;");insertLegacy(db.get(),"legacy",snapshot,source,"/gone/model.xlsm");insertLegacy(db.get(),"empty",book().dump(),"","");}
 {RecoveryStore store(path);const auto rows=store.records();require(rows.size()==2,"migration must retain every legacy record");bool found=false;for(const auto& row:rows)if(row.at("id")=="legacy"){found=true;require(row.at("workbook")==book()&&row.at("sourceBytes").get<std::string>()==source&&row.at("sourcePath")=="/gone/model.xlsm","migration preserves binary package and source path");}require(found,"legacy record retained");}
 {auto db=database(path);require(version(db.get())==3,"Legacy recovery schema must migrate to v3 journal integrity records");auto statement=prepare(db.get(),"SELECT snapshot FROM checkpoints WHERE id='legacy'");require(sqlite3_step(statement.get())==SQLITE_ROW,"retained legacy snapshot");const auto* bytes=static_cast<const char*>(sqlite3_column_blob(statement.get(),0));require(std::string(bytes,static_cast<std::size_t>(sqlite3_column_bytes(statement.get(),0)))==snapshot,"migration must not reserialize original snapshot bytes");sql(db.get(),"UPDATE checkpoints SET source='changed' WHERE id='legacy'");}
 RecoveryStore reopened(path);bool rejected=false;try{reopened.records();}catch(const std::runtime_error&){rejected=true;}require(rejected,"Migrated source corruption must be diagnosed");
}
void boundaries(){
 QTemporaryDir directory;const auto path=directory.filePath("boundaries.db").toStdString();RecoveryStore store(path);
 const std::string sourcePath("/original\0suffix",16);store.checkpoint("binary-path",book(),"",sourcePath);
 require(store.records()[0].at("sourcePath").get<std::string>()==sourcePath,"source path must retain embedded zero bytes");
 store.erase("binary-path");store.checkpoint("boundaries",book(),"A","BC");
 {auto db=database(path);sql(db.get(),"UPDATE checkpoints SET source='AB',path='C'");}
 bool rejected=false;try{store.records();}catch(const std::runtime_error& error){rejected=std::string(error.what()).find("checksum mismatch")!=std::string::npos;}
 require(rejected,"length prefixes must distinguish fields with an identical concatenation");
}
void migrationRollback(){
 QTemporaryDir directory;const auto path=directory.filePath("rollback.db").toStdString();const auto snapshot=book().dump(2);
 {auto db=database(path);sql(db.get(),"CREATE TABLE checkpoints(id TEXT PRIMARY KEY,snapshot BLOB NOT NULL,source BLOB NOT NULL,path TEXT NOT NULL);PRAGMA user_version=1;");insertLegacy(db.get(),"good",snapshot,"original","/gone/model.xlsm");insertLegacy(db.get(),"bad","{broken","package","/gone/bad.xlsm");}
 bool rejected=false;try{RecoveryStore store(path);}catch(const std::runtime_error& error){rejected=std::string(error.what()).find("corrupt")!=std::string::npos;}
 require(rejected,"invalid legacy snapshot must stop migration with a corruption diagnosis");
 auto db=database(path);require(version(db.get())==1,"failed migration must preserve original schema version");auto fields=prepare(db.get(),"PRAGMA table_info(checkpoints)");int columns=0;while(sqlite3_step(fields.get())==SQLITE_ROW)++columns;require(columns==4,"failed migration must roll back added integrity column");
 auto rows=prepare(db.get(),"SELECT id,snapshot,source FROM checkpoints ORDER BY id");require(sqlite3_step(rows.get())==SQLITE_ROW,"invalid record retained for recovery diagnosis");require(std::string(reinterpret_cast<const char*>(sqlite3_column_text(rows.get(),0)))=="bad","invalid legacy record must not be silently dropped");require(sqlite3_step(rows.get())==SQLITE_ROW,"valid record retained after rollback");const auto* bytes=static_cast<const char*>(sqlite3_column_blob(rows.get(),1));require(std::string(bytes,static_cast<std::size_t>(sqlite3_column_bytes(rows.get(),1)))==snapshot,"rollback preserves exact original snapshot bytes");require(sqlite3_step(rows.get())==SQLITE_DONE,"all legacy records retained without duplicates");
}
template<class Store> void appendDeltas(Store& store,const std::string& id,const Json& deltas){if constexpr(requires { store.append(id,deltas); })store.append(id,deltas);else throw std::runtime_error("Recovery store must persist ordered revision journals");}
template<class Store> void compactJournal(Store& store,const std::string& id,const Json& workbook){if constexpr(requires { store.compact(id,workbook); })store.compact(id,workbook);else throw std::runtime_error("Recovery store must compact journal checkpoints atomically");}
Json initialBook(){return {{"revision",0},{"sheets",Json::array({{{"id","sheet-1"},{"name","Sheet1"},{"cells",Json::array({{{"row",1},{"col",1},{"input","before"}}})}}})}};}
Json delta(int base,const std::string& text){return {{"version",1},{"baseRevision",base},{"revision",base+1},{"patch",false},{"changes",{{"cells",Json::array({{{"sheet","sheet-1"},{"row",1},{"col",1},{"cell",{{"row",1},{"col",1},{"input",text}}}}})},{"stale",Json::array()}}}};}
void journal(){QTemporaryDir directory;const auto path=directory.filePath("journal.db").toStdString();const std::string original("PK\0original",11);auto expected=initialBook();expected["revision"]=2;expected["sheets"][0]["cells"][0]["input"]="second";{RecoveryStore store(path);store.checkpoint("journal",initialBook(),original,"/gone/original.xlsx");appendDeltas(store,"journal",Json::array({delta(0,"first"),delta(1,"second")}));{auto db=database(path);auto statement=prepare(db.get(),"SELECT snapshot,source,(SELECT COUNT(*) FROM recovery_journal) FROM checkpoints WHERE id='journal'");require(sqlite3_step(statement.get())==SQLITE_ROW,"journal base retained");require(Json::parse(reinterpret_cast<const char*>(sqlite3_column_blob(statement.get(),0)),reinterpret_cast<const char*>(sqlite3_column_blob(statement.get(),0))+sqlite3_column_bytes(statement.get(),0)).at("revision")==0&&sqlite3_column_int(statement.get(),2)==2,"edits append deltas without rewriting the base snapshot or original package");require(std::string(static_cast<const char*>(sqlite3_column_blob(statement.get(),1)),sqlite3_column_bytes(statement.get(),1))==original,"journal retains original source bytes once");}}{RecoveryStore reopened(path);require(reopened.records()[0]["workbook"]==expected,"recovery replays ordered transaction deltas after restart");compactJournal(reopened,"journal",expected);require(reopened.records()[0]["workbook"]==expected&&reopened.records()[0]["sourceBytes"]==original,"compaction retains exact state and original source");auto db=database(path);auto count=prepare(db.get(),"SELECT COUNT(*) FROM recovery_journal");require(sqlite3_step(count.get())==SQLITE_ROW&&sqlite3_column_int(count.get(),0)==0,"compaction atomically discards its covered journal");reopened.erase("journal");require(reopened.records().empty(),"erase removes journal and checkpoint");}}
void journalIntegrity(){for(const auto* change:{"DELETE FROM recovery_journal WHERE revision=1","DELETE FROM recovery_journal WHERE revision=2","UPDATE recovery_heads SET revision=99","UPDATE recovery_journal SET previous='broken' WHERE revision=2","UPDATE recovery_journal SET delta='{}' WHERE revision=2"}){QTemporaryDir directory;const auto path=directory.filePath("corrupt-journal.db").toStdString();RecoveryStore store(path);store.checkpoint("journal",initialBook(),"original","/original");appendDeltas(store,"journal",Json::array({delta(0,"first"),delta(1,"second")}));{auto db=database(path);sql(db.get(),change);}bool rejected=false;try{store.records();}catch(const std::runtime_error& failure){rejected=std::string(failure.what()).find("corrupt")!=std::string::npos;}require(rejected,"missing head/middle/tail or altered journal must receive a corruption diagnosis");}QTemporaryDir directory;const auto path=directory.filePath("atomic.db").toStdString();RecoveryStore store(path);store.checkpoint("journal",initialBook(),"original","/original");bool rejected=false;try{appendDeltas(store,"journal",Json::array({delta(0,"first"),delta(7,"bad")}));}catch(const std::runtime_error&){rejected=true;}require(rejected&&store.records()[0]["workbook"]==initialBook(),"out of order batch rolls back all journal rows and head updates");}
template<class Driver> void persistSeed(Driver& driver,const std::string& id){if constexpr(requires { driver.persist(id); })driver.persist(id);else throw std::runtime_error("Recovery must persist a dirty seeded workbook without inventing an edit revision");}
template<class Driver> void backgroundDriver(){if constexpr(requires { Driver(std::string()); }){QTemporaryDir directory;const auto path=directory.filePath("background.db").toStdString();Driver driver(path);std::uint64_t durable=0;std::string error;driver.onDurable=[&](const std::string& id,std::uint64_t value){require(QThread::currentThread()==QCoreApplication::instance()->thread(),"durability callbacks return to the UI thread");require(id=="background","durability callback retains document identity");durable=value;};driver.onError=[&](const std::string& value){error=value;};driver.seed("background",initialBook(),std::make_shared<const std::string>("original-bytes"),"/original.xlsx");driver.flush();require(RecoveryStore(path).records().empty(),"seeding a clean workbook creates no visible recovery record");persistSeed(driver,"background");driver.flush();auto seeded=RecoveryStore(path).records();require(seeded.size()==1&&seeded[0]["workbook"]==initialBook()&&seeded[0]["sourceBytes"]=="original-bytes","explicit persistence retains a dirty seeded workbook and source without a revision change");driver.erase("background");driver.flush();Json deltas=Json::array();for(int i=0;i<130;++i)deltas.push_back(delta(i,"edit-"+std::to_string(i)));driver.append("background",std::move(deltas));driver.flush();QCoreApplication::processEvents();auto records=RecoveryStore(path).records();require(records.size()==1&&records[0]["workbook"]["revision"]==130&&records[0]["workbook"]["sheets"][0]["cells"][0]["input"]=="edit-129"&&records[0]["sourceBytes"]=="original-bytes"&&durable==130,"background worker durably replays and compacts ordered deltas before a flush barrier");{auto db=database(path);auto count=prepare(db.get(),"SELECT COUNT(*) FROM recovery_journal");require(sqlite3_step(count.get())==SQLITE_ROW&&sqlite3_column_int(count.get(),0)==0,"background worker compacts a long journal");}driver.erase("background");driver.flush();require(RecoveryStore(path).records().empty(),"erase barrier removes durable recovery");driver.append("background",Json::array({delta(130,"after-save")}));driver.flush();require(RecoveryStore(path).records()[0]["workbook"]["revision"]==131,"erase retains actor state for subsequent document deltas");driver.append("background",Json::array({delta(7,"out-of-order")}));bool failed=false;try{driver.flush();}catch(const std::exception&){failed=true;}QCoreApplication::processEvents();require(failed&&!error.empty(),"asynchronous failures surface through flush and the UI callback");}else throw std::runtime_error("Recovery must provide a background delta driver");}
void immutableSource(){QTemporaryDir directory;const auto path=directory.filePath("source-once.db").toStdString();RecoveryStore store(path);store.checkpoint("source-once",initialBook(),"large-original-package","/source.xlsx");appendDeltas(store,"source-once",Json::array({delta(0,"edited")}));{auto db=database(path);sql(db.get(),"CREATE TRIGGER original_source_once BEFORE UPDATE ON checkpoints BEGIN SELECT RAISE(ABORT,'compaction must not rewrite the original package row'); END;");}auto expected=initialBook();expected["revision"]=1;expected["sheets"][0]["cells"][0]["input"]="edited";compactJournal(store,"source-once",expected);require(store.records()[0]["workbook"]==expected&&store.records()[0]["sourceBytes"]=="large-original-package","compaction uses a separate base while the original package row remains immutable");}
void interruptedJournal(){QTemporaryDir directory;const auto path=directory.filePath("interrupted.db").toStdString();{RecoveryStore store(path);store.checkpoint("crash",initialBook(),"original","/original");appendDeltas(store,"crash",Json::array({delta(0,"first"),delta(1,"second")}));}const auto child=fork();require(child>=0,"fork crash probe");if(child==0){auto db=database(path);sql(db.get(),"BEGIN IMMEDIATE;DELETE FROM recovery_journal WHERE revision=2;UPDATE recovery_heads SET revision=999,digest='interrupted';");_exit(0);}int status=0;require(waitpid(child,&status,0)==child&&WIFEXITED(status)&&WEXITSTATUS(status)==0,"crash probe child terminates without committing");RecoveryStore reopened(path);require(reopened.records()[0]["workbook"]["revision"]==2&&reopened.records()[0]["workbook"]["sheets"][0]["cells"][0]["input"]=="second","crash between journal/head writes retains the last complete durable revision");{auto db=database(path);sql(db.get(),"CREATE TRIGGER interrupt_head BEFORE UPDATE ON recovery_heads BEGIN SELECT RAISE(ABORT,'injected head failure'); END;");}bool failed=false;try{appendDeltas(reopened,"crash",Json::array({delta(2,"lost")}));}catch(const std::runtime_error&){failed=true;}require(failed&&reopened.records()[0]["workbook"]["revision"]==2,"failed head update rolls back newly appended tail");{auto db=database(path);sql(db.get(),"DROP TRIGGER interrupt_head;CREATE TRIGGER interrupt_compaction BEFORE DELETE ON recovery_journal BEGIN SELECT RAISE(ABORT,'injected compaction failure'); END;");}failed=false;try{compactJournal(reopened,"crash",reopened.records()[0]["workbook"]);}catch(const std::runtime_error&){failed=true;}require(failed&&reopened.records()[0]["workbook"]["revision"]==2,"failed compaction rolls back replacement base and retains complete journal");}
void migrationV2(){QTemporaryDir directory;const auto path=directory.filePath("v2.db").toStdString();{RecoveryStore store(path);store.checkpoint("v2",initialBook(),"original-package","/original");}{auto db=database(path);sql(db.get(),"DROP TABLE recovery_journal;DROP TABLE recovery_heads;DROP TABLE recovery_bases;PRAGMA user_version=2;");}{RecoveryStore migrated(path);require(migrated.records()[0]["workbook"]==initialBook()&&migrated.records()[0]["sourceBytes"]=="original-package","v2 integrity checkpoint migrates to ordered journal without data changes");appendDeltas(migrated,"v2",Json::array({delta(0,"after-migration")}));require(migrated.records()[0]["workbook"]["revision"]==1,"migrated v2 checkpoint accepts its first ordered delta");}}
void sharedIdentity(){QTemporaryDir directory;const auto path=directory.filePath("shared.db").toStdString();{RecoveryStore initialize(path);}RecoveryDriver first(path),second(path);auto source=std::make_shared<const std::string>("original");first.seed("shared",initialBook(),source,"/original");first.append("shared",Json::array({delta(0,"first")}));first.flush();second.erase("shared");second.flush();first.append("shared",Json::array({delta(1,"after-erase")}));first.flush();auto state=RecoveryStore(path).records()[0]["workbook"];require(state["revision"]==2&&state["sheets"][0]["cells"][0]["input"]=="after-erase","a live actor recreates an externally erased recovery base before the next delta");second.seed("shared",std::move(state),source,"/original");second.append("shared",Json::array({delta(2,"foreign")}));second.flush();first.append("shared",Json::array({delta(2,"conflicting")}));bool failed=false;try{first.flush();}catch(const std::runtime_error&){failed=true;}auto retained=RecoveryStore(path).records()[0]["workbook"];require(failed&&retained["revision"]==3&&retained["sheets"][0]["cells"][0]["input"]=="foreign","actor conflicts cannot overwrite another writer's changed durable revision");}
void concurrentInitialization(){for(int i=0;i<3;++i){QTemporaryDir directory;const auto path=directory.filePath("concurrent.db").toStdString();RecoveryDriver first(path),second(path),third(path);first.flush();second.flush();third.flush();require(RecoveryStore(path).records().empty(),"concurrent fresh-window SQLite initialization succeeds without lock errors");}}
void futureVersion(){
 QTemporaryDir directory;const auto path=directory.filePath("future.db").toStdString();{RecoveryStore store(path);store.checkpoint("model",book(),"original","/original");}{auto db=database(path);sql(db.get(),"PRAGMA user_version=4");}
 bool rejected=false;try{RecoveryStore store(path);}catch(const std::runtime_error& error){rejected=std::string(error.what()).find("Unsupported recovery database version")!=std::string::npos;}
 require(rejected,"future recovery database must be refused without downgrade");auto db=database(path);require(version(db.get())==4,"future schema version must remain intact");auto count=prepare(db.get(),"SELECT COUNT(*) FROM checkpoints");require(sqlite3_step(count.get())==SQLITE_ROW&&sqlite3_column_int(count.get(),0)==1,"unsupported future database must retain all records");
}
}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{const std::string selected=argc>1?argv[1]:"all";if(selected=="all"||selected=="background")backgroundDriver<RecoveryDriver>();if(selected=="all"||selected=="immutableSource")immutableSource();if(selected=="all"||selected=="interruptedJournal")interruptedJournal();if(selected=="all"||selected=="migrationV2")migrationV2();if(selected=="all"||selected=="sharedIdentity")sharedIdentity();if(selected=="all"||selected=="concurrentInitialization")concurrentInitialization();if(selected=="all"||selected=="journal")journal();if(selected=="all"||selected=="journalIntegrity")journalIntegrity();if(selected=="all"||selected=="roundTrip")roundTrip();if(selected=="all"||selected=="migration")migration();if(selected=="all"||selected=="corruption")corruption();if(selected=="all"||selected=="boundaries")boundaries();if(selected=="all"||selected=="migrationRollback")migrationRollback();if(selected=="all"||selected=="futureVersion")futureVersion();std::cout<<"recovery tests passed\n";}catch(const std::exception& error){std::cerr<<"recovery test failed: "<<error.what()<<'\n';return 1;}}
